import { useState } from "react";

export function App() {
  const [plan, setPlan] = useState("starter");
  const [status, setStatus] = useState("idle");
  return (
    <div>
      <select data-testid="plan" value={plan} onChange={(event) => setPlan(event.target.value)}><option value="starter">Starter</option><option value="pro">Pro</option></select>
      <button data-testid="confirm-choice" onClick={() => setStatus(`Confirmed ${plan}`)}>Confirm choice</button>
      <span data-testid="choice-status">{status}</span>
    </div>
  );
}
